impl ::flatbuffers::Verifiable for LFV<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("VIEW", Self::VT_VIEW, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<&'_ str>>>>("FEATURE_NAMES", Self::VT_FEATURE_NAMES, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<&'_ str>>>>("FEATURE_UNITS", Self::VT_FEATURE_UNITS, false)?
            .visit_field::<i64>("WINDOW_START_MS", Self::VT_WINDOW_START_MS, false)?
            .visit_field::<i64>("WINDOW_END_MS", Self::VT_WINDOW_END_MS, false)?
            .visit_field::<u32>("MIN_POINTS", Self::VT_MIN_POINTS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<LFVRow>>>>("ROWS", Self::VT_ROWS, false)?
            .visit_field::<u32>("SOURCE_COUNT", Self::VT_SOURCE_COUNT, false)?
            .visit_field::<u32>("REFERENCE_COUNT", Self::VT_REFERENCE_COUNT, false)?
            .visit_field::<u32>("SKIPPED_COUNT", Self::VT_SKIPPED_COUNT, false)?
            .visit_field::<i64>("GENERATED_AT_MS", Self::VT_GENERATED_AT_MS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<LFVTestReport>>("REPORT", Self::VT_REPORT, false)?
            .finish();
        Ok(())
    }
}

