#[non_exhaustive]
#[derive(Debug, Clone, PartialEq)]
pub struct LFVT {
    pub VIEW: Option<alloc::string::String>,
    pub FEATURE_NAMES: Option<alloc::vec::Vec<alloc::string::String>>,
    pub FEATURE_UNITS: Option<alloc::vec::Vec<alloc::string::String>>,
    pub WINDOW_START_MS: i64,
    pub WINDOW_END_MS: i64,
    pub MIN_POINTS: u32,
    pub ROWS: Option<alloc::vec::Vec<LFVRowT>>,
    pub SOURCE_COUNT: u32,
    pub REFERENCE_COUNT: u32,
    pub SKIPPED_COUNT: u32,
    pub GENERATED_AT_MS: i64,
    pub REPORT: Option<alloc::boxed::Box<LFVTestReportT>>,
}

impl Default for LFVT {
    fn default() -> Self {
        Self {
            VIEW: None,
            FEATURE_NAMES: None,
            FEATURE_UNITS: None,
            WINDOW_START_MS: 0,
            WINDOW_END_MS: 0,
            MIN_POINTS: 0,
            ROWS: None,
            SOURCE_COUNT: 0,
            REFERENCE_COUNT: 0,
            SKIPPED_COUNT: 0,
            GENERATED_AT_MS: 0,
            REPORT: None,
        }
    }
}

impl LFVT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<LFV<'b>> {
        let VIEW = self.VIEW.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let FEATURE_NAMES = self.FEATURE_NAMES.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|s| _fbb.create_string(s)).collect();_fbb.create_vector(&w)
        });
        let FEATURE_UNITS = self.FEATURE_UNITS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|s| _fbb.create_string(s)).collect();_fbb.create_vector(&w)
        });
        let WINDOW_START_MS = self.WINDOW_START_MS;
        let WINDOW_END_MS = self.WINDOW_END_MS;
        let MIN_POINTS = self.MIN_POINTS;
        let ROWS = self.ROWS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let SOURCE_COUNT = self.SOURCE_COUNT;
        let REFERENCE_COUNT = self.REFERENCE_COUNT;
        let SKIPPED_COUNT = self.SKIPPED_COUNT;
        let GENERATED_AT_MS = self.GENERATED_AT_MS;
        let REPORT = self.REPORT.as_ref().map(|x|{
            x.pack(_fbb)
        });
        LFV::create(_fbb, &LFVArgs{
            VIEW,
            FEATURE_NAMES,
            FEATURE_UNITS,
            WINDOW_START_MS,
            WINDOW_END_MS,
            MIN_POINTS,
            ROWS,
            SOURCE_COUNT,
            REFERENCE_COUNT,
            SKIPPED_COUNT,
            GENERATED_AT_MS,
            REPORT,
        })
    }
}

